let reviewPendingAuthorLink=reviewReadAuthorLink();
function reviewReadAuthorLink(){const values=new URLSearchParams(location.search).getAll('author');if(!values.length)return null;return values.length===1&&/^[A-Za-z0-9_-]{1,64}$/.test(values[0])?{id:values[0]}:{invalid:true}}
function reviewAuthorLink(id){const url=new URL(location.pathname,location.origin);url.searchParams.set('author',id);return url.href}
function reviewApplyAuthorLink(){if(!reviewPendingAuthorLink||reviewAuthBusy||reviewAccountConnecting||!reviewReady||!S.user?.reviewService)return;const requested=reviewPendingAuthorLink;reviewPendingAuthorLink=null;if(requested.invalid){toast('作者链接无效，未改变当前页面。');return}reviewGoPublicAuthor({id:requested.id,name:'公开作者'})}
function reviewUpdateAuthorLocation(page){
 const url=new URL(location.href),author=page==='author'?reviewSelectedPublicAuthor():null;
 if(author){
  url.searchParams.set('author',author.id);
  for(const key of ['tutorial','version','comment','practice','path','pathVersion'])url.searchParams.delete(key);
  reviewPendingTutorialLink=false;
  reviewPendingPracticeLink=[];
  reviewPendingPathLink=[];
 }else url.searchParams.delete('author');
 if(url.href!==location.href)history.replaceState(null,'',url.href)
}
function reviewSelectedPublicAuthor(){const a=S.settings.publicAuthorSelection;return S.user?.reviewService&&a&&typeof a.name==='string'&&typeof a.id==='string'&&/^[A-Za-z0-9_-]{1,64}$/.test(a.id)?a:null}
function reviewGoPublicAuthor(author,context=reviewContext()){if(!reviewContextCurrent(context)||!author||typeof author.name!=='string'||typeof author.id!=='string'||!/^[A-Za-z0-9_-]{1,64}$/.test(author.id))return;S.settings.publicAuthorSelection={id:author.id,name:author.name};closeModal();navigate('author')}
function reviewPublicAuthorPage(){const a=reviewSelectedPublicAuthor();if(!a)return title('作者主页','请从公开教程、实践或路径的作者入口选择一位作者。');queueMicrotask(()=>reviewBindPublicAuthor());return `<section id="public-author-page"><header class="profile-head"><div class="avatar" id="public-author-page-avatar">${esc(Array.from(a.name)[0]||'人')}</div><div><h1 id="public-author-page-name">${esc(a.name)}</h1><p class="small muted">公开介绍与知识实践</p><a id="public-author-page-link" class="small" href="${esc(reviewAuthorLink(a.id))}">作者主页链接</a></div></header><section id="public-author-page-intro" class="box" aria-live="polite">正在核对当前公开介绍…</section><div id="public-author-page-content"></div><p id="public-author-page-error" class="error" role="alert"></p><button id="public-author-page-retry" class="ghost">重新读取作者主页</button></section>`}
async function reviewBindPublicAuthor(force=false){const host=document.getElementById('public-author-page'),a=reviewSelectedPublicAuthor();if(!host||!a||reviewAuthBusy||reviewAccountConnecting||!force&&host.dataset.bound==='true')return;host.dataset.bound='true';const context=reviewContext(),request=String(Number(host.dataset.generation||0)+1);host.dataset.generation=request;const intro=document.getElementById('public-author-page-intro'),content=document.getElementById('public-author-page-content'),error=document.getElementById('public-author-page-error'),retry=document.getElementById('public-author-page-retry');retry.onclick=()=>reviewBindPublicAuthor(true);intro.textContent='正在核对当前公开介绍…';content.innerHTML='';error.textContent='';const current=()=>host.isConnected&&reviewContextCurrent(context)&&host.dataset.generation===request;
 try{const r=await reviewKnowledgeRequest('/api/review-public-tutorials/author?id='+encodeURIComponent(a.id),{context});if(!current())return;if(r.ownerId!==context.ownerId||r.author?.id!==a.id||typeof r.author.name!=='string')throw Error('作者主页回执不一致，请重新读取。');const author=r.author;document.getElementById('public-author-page-name').textContent=author.name;document.getElementById('public-author-page-avatar').textContent=Array.from(author.name)[0]||'人';intro.innerHTML=author.profile?`<p>${esc(author.profile.tagline)}</p><p class="pre">${esc(author.profile.about)}</p><p class="small muted">${esc(author.profile.focus)}</p>`:'<p class="small muted">作者尚未公开个人介绍。</p>';
  if(author.id!==context.ownerId){const follow=document.createElement('button');follow.id='public-author-follow';follow.className='ghost';follow.textContent=reviewFollowedAuthors().some(a=>a.id===author.id)?'取消关注':'关注作者';const feedback=document.createElement('p');feedback.id='public-author-follow-status';feedback.className='small muted';feedback.setAttribute('role','status');intro.append(follow,feedback);follow.onclick=()=>reviewToggleAuthorFollow(author,context,follow,feedback)}
  const sections=[['tutorials','公开教程','/api/review-public-tutorials','tutorials'],['practices','公开实践','/api/review-public-practices','practices'],['paths','公开路径','/api/review-public-paths','paths']];content.innerHTML=sections.map(([kind,label])=>`<section class="box" style="margin:18px 0" id="author-${kind}-section"><div class="row between"><h2>${label}</h2><button class="ghost" id="author-${kind}-browse">查看完整目录</button></div><p class="small muted" role="status" id="author-${kind}-status">正在读取…</p><div id="author-${kind}-results"></div></section>`).join('');
  document.getElementById('author-tutorials-browse').onclick=()=>{if(current())reviewOpenPublicSearch('',author)};document.getElementById('author-practices-browse').onclick=()=>{if(current())reviewOpenAuthorPractices(author,context)};document.getElementById('author-paths-browse').onclick=()=>{if(current())reviewOpenPublicPaths('',author)};
  await Promise.all(sections.map(async([kind,label,url,key])=>{const results=document.getElementById('author-'+kind+'-results'),status=document.getElementById('author-'+kind+'-status');let generation=0;async function load(cursor='',history=[],notice=''){if(!current()||!results.isConnected)return;const g=++generation;results.innerHTML='';status.textContent='正在读取'+label+'…';try{const data=await reviewKnowledgeRequest(url+'?query=&authorId='+encodeURIComponent(author.id)+(cursor?'&cursor='+encodeURIComponent(cursor):''),{context});if(!current()||!results.isConnected||g!==generation)return;if(data.ownerId!==context.ownerId||data.authorId!==author.id||!Array.isArray(data[key])||data[key].some(v=>v.authorId!==author.id)||!Number.isSafeInteger(data.total)||data.total<0)throw Error('作者内容回执不一致，请重新读取。');const rows=data[key];status.textContent=`${notice}${data.total} 条${label}，本页 ${rows.length} 条。第 ${history.length+1} 页。`;
   if(kind==='tutorials'){results.innerHTML=rows.map((t,i)=>`<article class="list-row"><h3>${esc(t.title)}</h3><p class="small muted">${esc(t.target.title)} · 版本 ${esc(t.version.slice(0,8))}</p><details><summary>查看完整目标、方法与材料</summary><p class="pre">${esc(t.target.goal)}</p><p class="pre">${esc(t.method)}</p><p class="small pre">五分钟起步：${esc(t.startAction)}</p>${t.resources.map(reviewResourceLink).join('')}</details><button class="ghost" data-author-tutorial="${i}">查看目标与方法</button><button class="ghost" data-author-discussion="${i}">讨论与提问</button><button class="ghost" data-author-bookmark="${i}">收藏这个版本</button><a class="small" data-author-tutorial-link href="${esc(reviewTutorialLink(t))}">教程链接</a></article>`).join('');results.querySelectorAll('[data-author-tutorial]').forEach(b=>b.onclick=()=>{if(current()&&b.isConnected)reviewOpenSearchTarget(rows[Number(b.dataset.authorTutorial)],context,b,status,notice=>load('',[],notice))});results.querySelectorAll('[data-author-bookmark]').forEach(b=>b.onclick=()=>{if(current()&&b.isConnected)reviewBookmarkTutorial(rows[Number(b.dataset.authorBookmark)],context,b,status,notice=>load('',[],notice))});results.querySelectorAll('[data-author-discussion]').forEach(b=>b.onclick=()=>{if(current()&&b.isConnected)reviewOpenSearchTarget(rows[Number(b.dataset.authorDiscussion)],context,b,status,notice=>load('',[],notice),reviewOpenDiscussion)})}
   if(kind==='practices'){results.innerHTML=rows.map((p,i)=>`<article class="list-row"><h3>${esc(p.snapshot?.nodeTitle||(p.currentTarget?.title?'当前关联目标 · '+p.currentTarget.title:'公开行动记录'))}</h3><p class="small muted">${esc(dt(Date.parse(p.createdAt)))} · ${p.lightUp?'作者本人自证':'公开行动记录'}</p><p class="pre">${esc(p.text)}</p>${p.snapshotStatus==='bound'?`<details><summary>查看当时知识与材料</summary><p class="pre">${esc(p.snapshot.nodeGoal)}</p><p class="small pre">${esc(p.snapshot.methodTitle||'独立尝试')} · ${esc(p.snapshot.methodAuthor||'')}<br>${esc(p.snapshot.content||'')}</p><p class="small pre">起步：${esc(p.snapshot.five||'')}</p><p class="small muted">实际活动 ${clock(p.activity.actualMilliseconds)} · ${p.activity.segmentCount} 段</p>${Array.isArray(p.snapshot.resourceLinks)?p.snapshot.resourceLinks.map(reviewResourceLink).join(''):p.snapshot.resource?`<p class="pre small">${esc(p.snapshot.resource)}</p>`:''}</details>`:'<p class="small muted">这条旧记录尚未核对完整目标与活动快照。</p>'}${reviewPracticeLink(p)}${reviewPublicPracticeImages(p)}<button class="ghost" data-author-practice="${i}">查看当前目标与方法</button></article>`).join('');results.querySelectorAll('[data-author-practice]').forEach(b=>b.onclick=()=>{if(current()&&b.isConnected)reviewOpenPracticeTarget(rows[Number(b.dataset.authorPractice)],context,b,status)});results.querySelectorAll('[data-practice-image]').forEach(img=>img.onerror=()=>{if(current()&&img.isConnected){img.hidden=true;img.style.display='none';img.closest('a').hidden=true;img.closest('figure').querySelector('figcaption').textContent='图片暂时无法读取，请重新读取实践。'}})}
   if(kind==='paths'){results.innerHTML=rows.map((p,i)=>`<article class="list-row"><h3>${esc(p.title)}</h3><details><summary>查看完整目标顺序与来源</summary>${reviewPathBody(p)}</details><button class="ghost" data-author-path-save="${i}">收藏这个版本</button><button class="ghost" data-author-path-copy="${i}">复制为我的路径</button>${reviewPathLink(p)}<div class="row">${p.targets.map((t,j)=>`<button class="ghost" data-author-path-target="${i}:${j}">查看目标 · ${esc(t.title)}</button>`).join('')}</div></article>`).join('');results.querySelectorAll('[data-author-path-save]').forEach(b=>b.onclick=()=>{if(current()&&b.isConnected)reviewBookmarkPublicPath(rows[Number(b.dataset.authorPathSave)],context,b,status)});results.querySelectorAll('[data-author-path-copy]').forEach(b=>b.onclick=()=>{if(current()&&b.isConnected)reviewCopyPublicPath(rows[Number(b.dataset.authorPathCopy)],context,b,status)});results.querySelectorAll('[data-author-path-target]').forEach(b=>b.onclick=()=>{if(current()&&b.isConnected){const [i,j]=b.dataset.authorPathTarget.split(':').map(Number);reviewOpenServicePathTarget(rows[i],j,context)}})}
   if(!rows.length)results.innerHTML='<p class="small muted">当前没有可公开读取的'+label+'。</p>';if(history.length){const previous=document.createElement('button');previous.textContent='上一页'+label;previous.onclick=()=>load(history.at(-1),history.slice(0,-1));results.append(previous)}if(data.nextCursor){const next=document.createElement('button');next.textContent='下一页'+label;next.onclick=()=>load(data.nextCursor,[...history,cursor]);results.append(next)}
  }catch(e){if(current()&&results.isConnected&&g===generation){status.textContent=reviewIsNetworkError(e)?label+'读取未确认，请重试。':e.message;results.innerHTML='';const again=document.createElement('button');again.textContent='重新读取'+label;again.onclick=()=>load(cursor,history);results.append(again);if(cursor){const first=document.createElement('button');first.textContent='重新读取第一页'+label;first.onclick=()=>load();results.append(first)}}}}await load()}));
 }catch(e){if(current()){intro.textContent='公开介绍读取未确认。';content.innerHTML='';error.textContent=reviewIsNetworkError(e)?'作者主页连接未确认，请重试。':e.message}}
}
